def date_to_ordinal(s):
  m = re.match(r"^(\d{4})-(\d{2})-(\d{2})$", s)
  if not m:
    sys.stderr.write("bad date format: " + s + "\n")
    sys.exit(2)
  y = int(m.group(1))
  mo = int(m.group(2))
  da = int(m.group(3))
  if mo < 1 or mo > 12:
    sys.stderr.write("bad month: " + s + "\n")
    sys.exit(2)
  leap = (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)
  if leap:
    feb = 29
  else:
    feb = 28
  month_len = [31, feb, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
  maxd = month_len[mo - 1]
  if da < 1 or da > maxd:
    sys.stderr.write("bad day: " + s + "\n")
    sys.exit(2)
  n = 365 * (y - 1) + (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400
  idx = 0
  while idx < mo - 1:
    n = n + month_len[idx]
    idx = idx + 1
  n = n + da
  return n

